report_script:
columns = [
    {"label": "Account Name", "fieldname": "account_name", "fieldtype": "Data", "width": 250},
    {"label": "Balance", "fieldname": "balance", "fieldtype": "Currency", "width": 150},
    {"label": "Actions", "fieldname": "actions", "fieldtype": "HTML", "width": 120}
]
result = []
company = filters.get("company")
from_date = filters.get("from_date")
to_date = filters.get("to_date")

accounts = frappe.db.get_all("Account", filters={"root_type": "Income", "is_group": 0, "company": company}, fields=["name"], order_by="name")

for acc in accounts:
    gl_filters = {"account": acc.name, "is_cancelled": 0}
    if from_date:
        gl_filters["posting_date"] = [">=", from_date]
    if to_date:
        if "posting_date" in gl_filters:
            gl_filters["posting_date"] = ["between", [from_date, to_date]]
        else:
            gl_filters["posting_date"] = ["<=", to_date]

    gl_entries = frappe.db.get_all("GL Entry", filters=gl_filters, fields=["debit", "credit"])

    if "Income" == "Income":
        balance = sum((float(e.credit or 0) - float(e.debit or 0)) for e in gl_entries)
    else:
        balance = sum((float(e.debit or 0) - float(e.credit or 0)) for e in gl_entries)

    ledger_link = f'<a href="/app/query-report/General%20Ledger?account={acc.name}" class="btn btn-default btn-xs">View Ledger</a>'
    result.append({"account_name": acc.name, "balance": balance, "actions": ledger_link})

